import { useCallback, useEffect, useMemo, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import type { GroupedPermissions, PermissionItem, RoleRow } from '../types/roles.types';
import { useHasPermission } from '../hooks/usePermission';
import { cn } from '@/lib/utils';

const RoleFormPage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const isEdit = Boolean(id);
    const canSave = useHasPermission(isEdit ? 'edit_role' : 'create_role');
    const canLoadPermissions = useHasPermission('list_permission');

    const [name, setName] = useState('');
    const [isActive, setIsActive] = useState(true);
    const [groups, setGroups] = useState<GroupedPermissions>({});
    const [selectedIds, setSelectedIds] = useState<number[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    const load = useCallback(async () => {
        setLoading(true);
        try {
            if (isEdit && id) {
                const res = await apiGet<{ data: { permissions: GroupedPermissions; role: RoleRow | null } }>({
                    endpoint: `${endpoints.accessControl.rolePermissions}${id}`,
                });
                const payload = res.data?.data;
                setGroups(payload?.permissions ?? {});
                const role = payload?.role;
                if (role) {
                    setName(role.name ?? '');
                    setIsActive(role.is_active === 1 || role.is_active === true);
                    const ids = (role.permissions ?? []).map((p) => p.id).filter(Boolean);
                    setSelectedIds(ids);
                }
            } else {
                const res = await apiGet<{ data: GroupedPermissions }>({ endpoint: endpoints.accessControl.permissionList });
                setGroups(res.data?.data ?? {});
                setSelectedIds([]);
                setName('');
                setIsActive(true);
            }
        } catch {
            toast.error('تعذر تحميل البيانات');
        } finally {
            setLoading(false);
        }
    }, [id, isEdit]);

    useEffect(() => {
        if (canLoadPermissions) {
            load();
        } else {
            setLoading(false);
        }
    }, [load, canLoadPermissions]);

    const togglePermission = (permId: number) => {
        setSelectedIds((prev) => (prev.includes(permId) ? prev.filter((x) => x !== permId) : [...prev, permId]));
    };

    const allPermissionIds = useMemo(() => {
        const ids: number[] = [];
        for (const items of Object.values(groups)) {
            for (const p of items as PermissionItem[]) {
                if (typeof p.id === 'number') {
                    ids.push(p.id);
                }
            }
        }
        return ids;
    }, [groups]);

    const selectedSet = useMemo(() => new Set(selectedIds), [selectedIds]);
    const allSelected = allPermissionIds.length > 0 && allPermissionIds.every((id) => selectedSet.has(id));

    const toggleAll = () => {
        setSelectedIds((prev) => {
            const prevSet = new Set(prev);
            const nextAllSelected = allPermissionIds.length > 0 && allPermissionIds.every((id) => prevSet.has(id));
            return nextAllSelected ? [] : Array.from(new Set(allPermissionIds));
        });
    };

    const toggleGroup = (groupName: string) => {
        const items = groups[groupName] as PermissionItem[] | undefined;
        if (!items || items.length === 0) return;

        const groupIds = items.map((p) => p.id).filter((x): x is number => typeof x === 'number');
        if (groupIds.length === 0) return;

        setSelectedIds((prev) => {
            const next = new Set(prev);
            const groupAllSelected = groupIds.every((id) => next.has(id));
            if (groupAllSelected) {
                for (const id of groupIds) next.delete(id);
            } else {
                for (const id of groupIds) next.add(id);
            }
            return Array.from(next);
        });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!canSave) {
            toast.error('ليس لديك صلاحية');
            return;
        }
        if (!name.trim()) {
            toast.error('اسم الدور مطلوب');
            return;
        }
        setSaving(true);
        try {
            const body = {
                name: name.trim().toLowerCase(),
                is_active: isActive ? 1 : 0,
                permissions: selectedIds,
            };
            if (isEdit && id) {
                await apiPost({
                    endpoint: `${endpoints.accessControl.roleUpdate}${id}`,
                    body: { ...body, id },
                });
                toast.success('تم تحديث الدور');
            } else {
                await apiPost({
                    endpoint: endpoints.accessControl.roleCreate,
                    body,
                });
                toast.success('تم إنشاء الدور');
            }
            navigate('/access-control/roles');
        } catch (err: unknown) {
            const msg =
                err && typeof err === 'object' && 'response' in err
                    ? (err as { response?: { data?: { msg?: string } } }).response?.data?.msg
                    : null;
            toast.error(msg || 'فشل الحفظ');
        } finally {
            setSaving(false);
        }
    };

    if (!canLoadPermissions) {
        return <p className="mt-8 px-2 text-sm text-white-blue-700">ليس لديك صلاحية عرض قائمة الصلاحيات.</p>;
    }

    if (loading) {
        return <p className="mt-8 text-sm text-white-blue-700 px-2">جاري التحميل…</p>;
    }

    return (
        <div className="mx-auto mt-6 w-full max-w-4xl px-4 pb-14">
            <Link
                to="/access-control/roles"
                className="mb-5 inline-block text-sm font-medium text-primery-blue-600 hover:text-primery-blue-500 hover:underline"
            >
                ← العودة لقائمة الأدوار
            </Link>
            <UnderlineHeading text={isEdit ? 'تعديل دور' : 'إضافة دور'} />
            <form
                onSubmit={handleSubmit}
                className="mt-8 space-y-6 rounded-2xl border border-[#E4E2EC] bg-white p-6 shadow-[0_12px_40px_-16px_rgba(12,12,13,0.12)] sm:p-8"
            >
                <div>
                    <label className="text-sm font-medium text-primery-blue-500 block mb-2">اسم الدور</label>
                    <Input value={name} onChange={(e) => setName(e.target.value)} className="max-w-md" dir="ltr" />
                </div>
                <label className="flex items-center gap-2 text-sm">
                    <input type="checkbox" checked={isActive} onChange={(e) => setIsActive(e.target.checked)} />
                    الدور مفعّل
                </label>
                <div>
                    <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-3">
                        <h3 className="text-base font-semibold text-primery-blue-600">الصلاحيات</h3>
                        <div className="flex items-center gap-2">
                            <button
                                type="button"
                                onClick={toggleAll}
                                className={cn(
                                    'rounded-lg border px-3 py-1.5 text-xs font-medium transition-colors',
                                    allSelected
                                        ? 'border-[#E4E2EC] bg-white text-white-blue-700 hover:bg-white-blue-50'
                                        : 'border-primery-blue-200 bg-primery-blue-500/5 text-primery-blue-700 hover:bg-primery-blue-500/10',
                                )}
                            >
                                {allSelected ? 'إلغاء تحديد الكل' : 'تحديد الكل'}
                            </button>
                            <span className="text-xs text-white-blue-600">
                                تم تحديد {selectedIds.length} / {allPermissionIds.length}
                            </span>
                        </div>
                    </div>
                    <div className="max-h-[480px] space-y-5 overflow-y-auto rounded-xl border border-[#EEF0F4] bg-[#FAFAFC] p-4 pe-2">
                        {Object.entries(groups).map(([groub, items]) => (
                            <section key={groub}>
                                <div className="mb-2 flex items-center justify-between gap-3">
                                    <h4 className="text-sm font-semibold text-primery-blue-600">{groub}</h4>
                                    <button
                                        type="button"
                                        onClick={() => toggleGroup(groub)}
                                        className="rounded-lg border border-[#E4E2EC] bg-white px-2.5 py-1 text-[11px] font-medium text-white-blue-700 hover:bg-white-blue-50"
                                    >
                                        {(() => {
                                            const ids = (items as PermissionItem[])
                                                .map((p) => p.id)
                                                .filter((x): x is number => typeof x === 'number');
                                            const groupAllSelected = ids.length > 0 && ids.every((id) => selectedSet.has(id));
                                            return groupAllSelected ? 'إلغاء تحديد القسم' : 'تحديد القسم';
                                        })()}
                                    </button>
                                </div>
                                <div className="grid gap-2 sm:grid-cols-2">
                                    {(items as PermissionItem[]).map((p) => (
                                        <label
                                            key={p.id}
                                            className="flex cursor-pointer items-center gap-2 rounded-lg border border-transparent bg-white px-2 py-2 text-sm transition-colors hover:border-primery-blue-200"
                                        >
                                            <input
                                                type="checkbox"
                                                checked={selectedIds.includes(p.id)}
                                                onChange={() => togglePermission(p.id)}
                                                className="rounded border-[#D8D6DE] text-primery-blue-600 focus:ring-primery-blue-500"
                                            />
                                            <span className="font-mono text-xs text-white-blue-900">{p.name}</span>
                                        </label>
                                    ))}
                                </div>
                            </section>
                        ))}
                    </div>
                </div>
                <PrimaryButton type="submit" disabled={saving || !canSave}>
                    {saving ? 'جاري الحفظ…' : 'حفظ'}
                </PrimaryButton>
            </form>
        </div>
    );
};

export default RoleFormPage;
